    id: "uuid",
    org_id: "uuid",
    unit_id: "uuid",
    tenant_id: "uuid",
    start_date: "date",
    end_date: "date",
    monthly_rent_sen: "bigint",
    deposit_sen: "bigint",
  },
  invoices: {
    id: "uuid",
    org_id: "uuid",
    lease_id: "uuid",
    kind: "text",
    period_index: "integer",
    period_start: "date",
    period_end: "date",
    due_date: "date",
    amount_sen: "bigint",
  },
  payments: {
    id: "uuid",
    org_id: "uuid",
    lease_id: "uuid",
    amount_sen: "bigint",
    unapplied_sen: "bigint",
    method: "text",
